"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * EARNINGS CHART: a bar chart that changes instead of redrawing
 *
 *   arrive    the first time it's on screen the bars grow up out
 *             of the baseline one after another and the total
 *             rolls up from zero
 *   period    6M, 1Y, All: the pill is thrown to the choice. Bars
 *             the two periods share glide to their new place and
 *             height, bars that leave fold away on their side,
 *             new ones grow in, the scale's labels roll and so
 *             does the total
 *   hover     a thin line column follows the pointer from bar to
 *             bar and the readout at its top slides along, its
 *             month morphing and its amount rolling
 *   change    the difference from the period before sits in a
 *             chip that turns emerald or red, its arrow turning
 *             with it
 *
 * The plot is one tab stop: arrow keys move between bars and
 * the readout is announced. Every figure is also in a table for
 * screen readers.
 * ───────────────────────────────────────────────────────── */

export interface EarningsBar {
  /** Stays the same across periods for the same month, so shared bars glide instead of popping. */
  key: string;
  /** Under the bar, e.g. "Aug". */
  label: string;
  value: number;
  /** In the readout, e.g. "August 2026". Defaults to label. */
  title?: string;
}

export interface EarningsPeriod {
  id: string;
  /** In the switch, e.g. "6M". */
  label: string;
  bars: EarningsBar[];
  /** The total of the period before, for the change chip. */
  previous?: number;
  /** After the chip, e.g. "vs the 6 months before". */
  comparison?: string;
}

export interface EarningsChartProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange"
> {
  title?: string;
  periods: EarningsPeriod[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (id: string) => void;
  /** Intl.NumberFormat options for amounts. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  /** The bar drawn in your primary colour, by key. Defaults to the last bar. */
  highlight?: string;
}

type Column = EarningsBar & {
  left: number;
  width: number;
  height: number;
  index: number;
  leaving?: "start" | "end";
};

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const GLIDE = "cubic-bezier(0.77,0,0.175,1)";
const MORPH = 560;
const PLOT = 176; // the bars' area
const HEADROOM = 30; // above the tallest bar, for the readout
const LABELS = 26;
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const CURRENCY: Intl.NumberFormatOptions = {
  style: "currency",
  currency: "USD",
  maximumFractionDigits: 0,
};

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** A round top for the scale: 4,820 → 5,000. */
function niceMax(value: number) {
  if (value <= 0) return 1;
  const step = 10 ** Math.floor(Math.log10(value));
  for (const m of [1, 1.2, 1.5, 2, 2.5, 3, 4, 5, 6, 8, 10])
    if (m * step >= value) return m * step;
  return 10 * step;
}

/** One bar and its label. It grows out of the baseline when it first appears, and folds away when it leaves. */
function ColumnView({
  col,
  grown,
  delay,
  tone,
  reduced,
  label,
}: {
  col: Column;
  grown: boolean;
  delay: number;
  tone: string;
  reduced: boolean;
  label: boolean;
}) {
  const [born, setBorn] = React.useState(false);
  React.useEffect(() => {
    let inner = 0;
    const outer = requestAnimationFrame(
      () => (inner = requestAnimationFrame(() => setBorn(true))),
    );
    return () => {
      cancelAnimationFrame(outer);
      cancelAnimationFrame(inner);
    };
  }, []);
  const up = grown && born && !col.leaving;
  return (
    <div
      aria-hidden="true"
      className="absolute top-0 h-full"
      style={{
        left: `${col.left}%`,
        width: `${col.width}%`,
        opacity: col.leaving ? 0 : 1,
        transition: reduced
          ? "none"
          : `left ${MORPH}ms ${GLIDE}, width ${MORPH}ms ${GLIDE}, opacity ${col.leaving ? 240 : 360}ms ${EASE}`,
      }}
    >
      <div
        className={`absolute bottom-[26px] left-1/2 w-[min(24px,62%)] -translate-x-1/2 rounded-t-[4px] ${tone}`}
        style={{
          height: up ? Math.max(2, col.height) : 0,
          transition: reduced
            ? "none"
            : `height 640ms ${EASE} ${delay}ms, background-color 300ms ${EASE}`,
        }}
      />
      <span
        className="absolute bottom-0 left-1/2 -translate-x-1/2 whitespace-nowrap text-[11px] leading-[18px] text-muted-foreground"
        style={{
          opacity: label ? 1 : 0,
          transition: reduced ? "none" : `opacity 300ms ${EASE}`,
        }}
      >
        {col.label}
      </span>
    </div>
  );
}

export function EarningsChart({
  title = "Earnings",
  periods,
  value,
  defaultValue,
  onValueChange,
  format = CURRENCY,
  locales,
  highlight,
  className = "",
  ...props
}: EarningsChartProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [own, setOwn] = React.useState(
    defaultValue ?? periods[periods.length - 1]?.id,
  );
  const periodId = value ?? own;
  const period = periods.find((p) => p.id === periodId) ?? periods[0];
  const bars = period?.bars ?? [];
  // Set by the card's width in CSS and measured below.
  const [plotH, setPlotH] = React.useState(PLOT);
  const total = bars.reduce((sum, b) => sum + b.value, 0);
  const max = niceMax(Math.max(0, ...bars.map((b) => b.value)));
  const slot = bars.length ? 100 / bars.length : 100;
  const layout: Column[] = bars.map((b, index) => ({
    ...b,
    index,
    left: index * slot,
    width: slot,
    height: (b.value / max) * (plotH - HEADROOM),
  }));
  const hi = highlight ?? bars[bars.length - 1]?.key;

  const [visible, setVisible] = React.useState(false);
  const [active, setActive] = React.useState<number | null>(null);
  const [keyboard, setKeyboard] = React.useState(false);
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const [prev, setPrev] = React.useState(() => ({
    id: periodId,
    bars,
    layout,
  }));
  const [pill, setPill] = React.useState({ left: 0, width: 0, ready: false });
  const rootRef = React.useRef<HTMLDivElement>(null);
  const plotRef = React.useRef<HTMLDivElement>(null);
  const barsRef = React.useRef<HTMLDivElement>(null);
  const chipRefs = React.useRef<(HTMLButtonElement | null)[]>([]);
  const [width, setWidth] = React.useState(0);

  // A new period: bars it doesn't have fold away on the side they were on, past the bars both periods share.
  if (prev.id !== periodId) {
    const keys = new Set(bars.map((b) => b.key));
    const shared = prev.layout
      .filter((c) => keys.has(c.key))
      .map((c) => c.index);
    const firstShared = shared.length
      ? Math.min(...shared)
      : prev.layout.length;
    setLeaving(
      prev.layout
        .filter((c) => !keys.has(c.key))
        .map((c) => {
          const side = c.index < firstShared ? "start" : "end";
          // Same key as before, so the bar that was there is the one that folds away.
          return {
            ...c,
            leaving: side,
            left: side === "start" ? 0 : 100,
            width: 0,
            height: 0,
          };
        }),
    );
    setPrev({ id: periodId, bars, layout });
    setActive(null);
  } else if (prev.bars !== bars) {
    setPrev({ id: periodId, bars, layout });
  }

  React.useEffect(() => {
    if (!leaving.length) return;
    const timer = window.setTimeout(() => setLeaving([]), MORPH);
    return () => window.clearTimeout(timer);
  }, [leaving]);

  // The plot's height is set by the card's width in CSS; read it so the drawing fits.
  React.useLayoutEffect(() => {
    const el = plotRef.current;
    if (!el) return;
    const measure = () =>
      setPlotH((h) => {
        const next = el.offsetHeight - LABELS;
        return next > 0 && next !== h ? next : h;
      });
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  React.useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { rootMargin: "0px 0px -10% 0px" },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  // Narrow bars show every other label (or fewer), always keeping the latest.
  React.useLayoutEffect(() => {
    const el = barsRef.current;
    if (!el) return;
    const measure = () =>
      setWidth((w) => (w === el.offsetWidth ? w : el.offsetWidth));
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);
  const every =
    width && bars.length
      ? Math.max(1, Math.ceil(30 / (width / bars.length)))
      : 1;

  React.useLayoutEffect(() => {
    const el = chipRefs.current[periods.findIndex((p) => p.id === periodId)];
    if (!el) return;
    setPill((p) =>
      p.left === el.offsetLeft && p.width === el.offsetWidth
        ? p
        : { left: el.offsetLeft, width: el.offsetWidth, ready: p.width > 0 },
    );
  }, [periodId, periods]);

  const choose = (next: string) => {
    if (next === periodId) return;
    if (value === undefined) setOwn(next);
    onValueChange?.(next);
  };

  const pointAt = (clientX: number) => {
    const r = barsRef.current?.getBoundingClientRect();
    if (!r || !bars.length) return null;
    return Math.min(
      bars.length - 1,
      Math.max(0, Math.floor(((clientX - r.left) / r.width) * bars.length)),
    );
  };

  const onKeyDown = (e: React.KeyboardEvent) => {
    if (!bars.length) return;
    const from =
      active ??
      Math.max(
        0,
        bars.findIndex((b) => b.key === hi),
      );
    const moves: Record<string, number> = {
      ArrowLeft: from - 1,
      ArrowRight: from + 1,
      Home: 0,
      End: bars.length - 1,
    };
    if (e.key === "Escape") return setActive(null);
    if (!(e.key in moves)) return;
    e.preventDefault();
    setKeyboard(true);
    setActive(
      Math.min(
        bars.length - 1,
        Math.max(0, active === null ? from : moves[e.key]),
      ),
    );
  };

  const fmt = (n: number) => new Intl.NumberFormat(locales, format).format(n);
  const change = period?.previous
    ? (total - period.previous) / period.previous
    : null;
  // The chip folds away for a period with nothing to compare against, holding its last figure while it goes.
  const [lastChange, setLastChange] = React.useState(change ?? 0);
  if (change !== null && change !== lastChange) setLastChange(change);
  const shownChange = change ?? lastChange;
  const up = shownChange >= 0;
  const comparable = periods.some((p) => p.previous);
  const shown = active !== null ? bars[active] : null;
  const col = active !== null ? layout[active] : null;
  const compact = {
    ...format,
    notation: "compact" as const,
    minimumFractionDigits: 0,
    maximumFractionDigits: 1,
  };

  return (
    <div
      ref={rootRef}
      className={`@container w-full rounded-[22px] bg-background shadow-[0_0_0_1px_var(--border)] ${className}`}
      {...props}
    >
      <div className="p-4 @md:p-5 [--gutter:30px] @md:[--gutter:40px] [--plot:148px] @md:[--plot:176px]">
        {/* The title and its control share a row; the figures sit under both. */}
        <div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-2">
          <p className="text-[12px] text-muted-foreground @md:text-[13px]">
            {title}
          </p>
          <div
            role="radiogroup"
            aria-label="Period"
            className="relative -my-1 inline-flex shrink-0 rounded-full bg-muted p-0.5"
          >
            <span
              aria-hidden="true"
              className="absolute inset-y-0.5 left-0 rounded-full bg-background shadow-[0_0_0_1px_var(--border)]"
              style={{
                width: pill.width,
                transform: `translateX(${pill.left}px)`,
                transition:
                  pill.ready && !reduced
                    ? `transform 460ms ${THROW}, width 380ms ${EASE}`
                    : "none",
              }}
            />
            {periods.map((p, i) => {
              const selected = p.id === periodId;
              return (
                <button
                  key={p.id}
                  ref={(el) => {
                    chipRefs.current[i] = el;
                  }}
                  type="button"
                  role="radio"
                  aria-checked={selected}
                  tabIndex={selected ? 0 : -1}
                  onClick={() => choose(p.id)}
                  onKeyDown={(e) => {
                    if (e.key !== "ArrowRight" && e.key !== "ArrowLeft") return;
                    e.preventDefault();
                    const next =
                      (i + (e.key === "ArrowRight" ? 1 : -1) + periods.length) %
                      periods.length;
                    choose(periods[next].id);
                    chipRefs.current[next]?.focus();
                  }}
                  className={`cursor-pointer relative h-6 rounded-full px-2.5 text-[11.5px] font-medium @md:h-7 @md:px-3 @md:text-[12.5px] tabular-nums transition-colors duration-300 ${FOCUS} ${
                    selected
                      ? "text-foreground"
                      : "text-muted-foreground hover:text-foreground"
                  }`}
                >
                  {p.label}
                </button>
              );
            })}
          </div>
        </div>
        <p className="mt-0.5 text-[22px] font-medium leading-tight tracking-[-0.03em] @md:text-[26px] text-foreground">
          <NumberRoll
            value={visible ? total : 0}
            format={format}
            locales={locales}
            duration={1000}
          />
        </p>
        {(comparable || period?.comparison) && (
          <p className="mt-1 flex items-center text-[11.5px] text-muted-foreground @md:text-[12.5px]">
            <span
              className="grid"
              style={{
                gridTemplateColumns: change !== null ? "1fr" : "0fr",
                opacity: change !== null ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `grid-template-columns 420ms ${EASE}, opacity 240ms ${EASE}`,
              }}
            >
              <span className="min-w-0 pr-2 [clip-path:inset(-4px_-2px)]">
                <span
                  className={`inline-flex items-center gap-1 whitespace-nowrap rounded-full px-1.5 py-px font-medium tabular-nums transition-colors duration-300 ${
                    up
                      ? "bg-emerald-500/10 text-emerald-600"
                      : "bg-red-500/10 text-red-600 dark:text-red-400"
                  }`}
                >
                  <svg
                    viewBox="0 0 12 12"
                    aria-hidden="true"
                    className="size-3"
                    style={{
                      transform: up ? "none" : "rotate(180deg)",
                      transition: reduced ? "none" : `transform 420ms ${THROW}`,
                    }}
                  >
                    <path
                      d="M6 9.5V2.5M2.8 5.6 6 2.5l3.2 3.1"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="1.5"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                  </svg>
                  <NumberRoll
                    value={visible ? Math.abs(shownChange) : 0}
                    format={{ style: "percent", maximumFractionDigits: 1 }}
                    duration={800}
                  />
                </span>
              </span>
            </span>
            <span className="whitespace-nowrap">
              <TextMorph>{period?.comparison ?? " "}</TextMorph>
            </span>
          </p>
        )}

        <div
          ref={plotRef}
          role="group"
          tabIndex={0}
          aria-label={`${title}, ${period?.label ?? ""}. Use the arrow keys to read each bar.`}
          onKeyDown={onKeyDown}
          onBlur={() => keyboard && (setActive(null), setKeyboard(false))}
          onPointerMove={(e) => {
            setKeyboard(false);
            setActive(pointAt(e.clientX));
          }}
          onPointerDown={(e) => setActive(pointAt(e.clientX))}
          onPointerLeave={(e) => e.pointerType === "mouse" && setActive(null)}
          className={`relative mt-4 touch-pan-y @md:mt-5 select-none rounded-lg ${FOCUS}`}
          style={{ height: `calc(var(--plot) + ${LABELS}px)` }}
        >
          {/* The scale: rolling labels in the gutter, the top and the middle as fine lines, and the baseline. */}
          {[1, 0.5, 0].map((f) => (
            <div
              key={f}
              aria-hidden="true"
              className="absolute right-0"
              style={{ left: 0, top: HEADROOM + (1 - f) * (plotH - HEADROOM) }}
            >
              <span
                className="absolute left-0 top-0 -translate-y-1/2 text-[10.5px] tabular-nums leading-none text-muted-foreground/80"
                style={{
                  width: "calc(var(--gutter) - 8px)",
                  textAlign: "right",
                }}
              >
                <NumberRoll
                  value={visible ? max * f : 0}
                  format={compact}
                  locales={locales}
                  duration={700}
                />
              </span>
              <div
                className="border-t border-border"
                style={{ marginLeft: "var(--gutter)" }}
              />
            </div>
          ))}

          <div
            ref={barsRef}
            className="absolute inset-y-0 right-0"
            style={{ left: "var(--gutter)" }}
          >
            {/* The hovered column: a thin line lane from the readout down to the baseline. */}
            <div
              aria-hidden="true"
              className="pointer-events-none absolute rounded-[10px] bg-foreground/[0.02] shadow-[inset_0_0_0_1px_var(--border)]"
              style={{
                top: 2,
                height: plotH - 2,
                left: col ? `calc(${col.left}% + 2px)` : 0,
                width: col ? `calc(${col.width}% - 4px)` : 0,
                opacity: col ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `left 380ms ${THROW}, width 380ms ${EASE}, opacity 200ms ${EASE}`,
              }}
            />

            {[
              ...layout,
              ...leaving.filter((l) => !bars.some((b) => b.key === l.key)),
            ].map((c) => (
              <ColumnView
                key={c.key}
                col={c}
                grown={visible}
                delay={c.leaving ? 0 : Math.min(c.index, 12) * 28}
                label={!c.leaving && (bars.length - 1 - c.index) % every === 0}
                reduced={reduced}
                tone={
                  c.key === hi
                    ? "bg-primary"
                    : active !== null && bars[active]?.key === c.key
                      ? "bg-foreground/25"
                      : active !== null
                        ? "bg-foreground/[0.07]"
                        : "bg-foreground/[0.11]"
                }
              />
            ))}

            {/* The readout rides the top of the lane: month morphs, amount rolls. */}
            <div
              aria-hidden="true"
              className="pointer-events-none absolute top-[5px] flex h-[22px] -translate-x-1/2 items-center gap-1.5 whitespace-nowrap rounded-full bg-background px-2.5 text-[11.5px] shadow-[0_0_0_1px_var(--border)]"
              style={{
                left: col
                  ? `clamp(56px, ${col.left + col.width / 2}%, calc(100% - 56px))`
                  : "50%",
                opacity: shown ? 1 : 0,
                scale: shown ? "1" : "0.94",
                transition: reduced
                  ? "none"
                  : `left 380ms ${THROW}, opacity 200ms ${EASE}, scale 260ms ${EASE}`,
              }}
            >
              <span className="text-muted-foreground">
                <TextMorph>
                  {shown ? (shown.title ?? shown.label) : " "}
                </TextMorph>
              </span>
              <span className="font-medium tabular-nums text-foreground">
                <NumberRoll
                  value={shown?.value ?? 0}
                  format={format}
                  locales={locales}
                  duration={600}
                />
              </span>
            </div>
          </div>
        </div>

        <p aria-live="polite" className="sr-only">
          {keyboard && shown
            ? `${shown.title ?? shown.label}: ${fmt(shown.value)}`
            : ""}
        </p>
        <table className="sr-only">
          <caption>
            {title}, {period?.label}: {fmt(total)}
          </caption>
          <tbody>
            {bars.map((b) => (
              <tr key={b.key} id={`${id}-${b.key}`}>
                <th scope="row">{b.title ?? b.label}</th>
                <td>{fmt(b.value)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

